import heapq
from typing import List

def find_smallest_color(path: List[int], needs: List[int]) -> int:
    smallest_color = float('inf')
    for i in range(len(path) - 1, -1, -1):
        if path[i] in needs:
            smallest_color = min(smallest_color, needs[path[i]])
    return smallest_color

def can_make_delivery(start: int, end: int, needs: List[int], scheduling_events: List[List[int]]) -> bool:
    # Perform Dijkstra's algorithm to find all shortest paths to the destinations
    # and check if all destinations have completed scheduling events in their required colors
    # or, find the smallest color that forms a double rainbow
    distances = {city: float('inf') for city in range(1, n + 1)}
    distances[start] = 0
    prev = {city: None for city in range(1, n + 1)}
    heap = [(0, start)]

    while heap:
        _, current_city = heapq.heappop(heap)
        if current_city == end:
            for neighbor in range(1, n + 1):
                if needs[neighbor] == find_smallest_color(prev[neighbor], needs):
                    return True
            return False
        if distances[current_city] < distances[neighbor]:
            continue

