def game_winner(piles):
    n = len(piles)
    dp = [0] * (n + 1)

    for i in range(n):
        if i > 0:
            dp[i] = dp[i-1] + 1
        for j in range(i+2, n+1):
            if n % j == 0 and sum(piles[i:j]) % j == 0:
                dp[j] = max(dp[j], dp[i] + 1)

