    points.sort()
    # Find the farthest pairs of points and keep only k - 1 of them
    farthest_pairs = []
    diameter = float('inf')
    points_taken = set()

    for i in range(n - 1):
        for j in range(n - i - 1):
            diff = abs(points[i][0] - points[n - 1 - j][0])
            if diff <= diameter:
                farthest_pairs.append((points[i], points[n - 1 - j]))
            else:
                diameter = diff

    # If k is equal to n, return all points without deletion
    if len(farthest_pairs) == k:
        for i in range(n):
            if i not in points_taken:
                print(i + 1)
        return

    # We can delete all points in farthest_pairs, except the k-1 with the smallest diameter
    remaining_points = set(points[i][0] for i in range(n) if points[i] not in farthest_pairs) - points_taken
    for _ in range(k - 1):
        points_taken.add(min(remaining_points))
        remaining_points.remove(remaining_points.intersection(remaining_points, set(range(n))))

    # Print the deleted points
    for i in range(n):
        if i not in points_taken:
            print(i + 1)

