class DSU:
    def __init__(self, n):
        self.parents = list(range(n))
        self.ranks = [0] * n

    def find(self, x):
        if self.parents[x] != x:
            self.parents[x] = self.find(self.parents[x])
        return self.parents[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            if self.ranks[rootX] < self.ranks[rootY]:
                self.parents[rootX] = rootY
            elif self.ranks[rootX] > self.ranks[rootY]:
                self.parents[rootY] = rootX
            else:
                self.parents[rootY] = rootX
                self.ranks[rootX] += 1

def solve(n, m, c, queries):
    dsu = DSU(n)

    for i in range(m):
        x, y, z = map(int, input().split())
        dsu.union(x - 1, y - 1)
        added = query_exists(x - 1, y - 1)
        if added:
            print("Yes")
        else:
            print("No")

    for query in queries:
        x, y = map(int, input().split())
        added = query_exists(x - 1, y - 1)
        if added:
            print("No")
        else:
            print("Yes")

def query_exists(x, y):
    p_x = dsu.find(x)
    p_y = dsu.find(y)
    if p_x == p_y:
        return True
    else:
        return False

