from collections import defaultdict, deque

def process_flips(n_village, roads, updates):
    def find_parent(v):
        if parent[v] != v:
            parent[v] = find_parent(parent[v])
        return parent[v]

    def union_sets(x, y):
        px, py = find_parent(x), find_parent(y)
        if px == py:
            return 0
        parent[px] = py
        size[py] += size[px]
        return 1

    parent = {i: i for i in range(1, n_village + 1)}
    size = {i: 1 for i in range(1, n_village + 1)}
    edges = {}

    # Build graph and update sets
    for u, v, t in roads:
        edges[(min(u, v), max(u, v)) if t else (max(u, v), min(u, v))] = t
        if t:
            union_sets(u, v)

    # Process updates, marking edges that change the parent or size
    for idx in updates:
        u, v, t = roads[idx]
        if t != edges.get((u, v), -1):
            result = union_sets(u, v)
            if idx:
                del edges[(u, v)]
                if edges.get((v, u), -1) != t:  # Mark edges that change the parent or size
                    result = 0 if result else 1
                    edges[(v, u)] = edges[(u, v)] = t = result
            else:
                edges[(u, v)] = result  # Mark edges that we're not flipping
                if v in edges:
                    del edges[v]  # Remove this vertex from the graph
            if v == 1 and idx and (u, v) not in result:  # Special case where we're going back to the start
