        d1 = find_root(src, graph_sizes, edges)
        if src == start:  # Avoid parent circle
            continue
        path_len = graph_sizes[src] * 2
        if (d1 != dst) or (not dst):
            pairs.append((path_len, graph_sizes[start] * 2))
        else:
            path_len -= graph_sizes[dst]
        if graph_sizes[d1]:
            graph_sizes[d1] -= graph_sizes[dst]  # Reduce buffer sizes
            path_len -= (graph_sizes[d1] * 2)
        else:
            del graph_sizes[d1]  # Node disappeared
    # Assign each path pair a parent node
    for node, size in path_sizes.items():
        for path_len, orig_size in pairs:
            if (node, node) in edges and edges[(node, node)] and path_len != graph_sizes[node]:
                queue = deque([(node, 2, path_len)])
                route = set()
                while queue:
                    src, lib, old_size = queue.popleft()
                    for step, (d1, src_prime, val) in enumerate(graph_sizes):
                        if old_size:
                            nodes = edges[(d1, src_prime)]
                        else:
                            nodes = []
                        new_len = old_size - lib * nodes.get(step, 0)
                        if old_size and path_len != graph_sizes[src]:
                            if nodes:
