def gcd(x, m):
    while m:
        x, m = m, x % m
    return x

def min_traps(m, x):
    if m < x:
        return (m - 1) // x

    num_traps = 0
    for i in range(1, m):
        if gcd(x, i) == 1:
            num_traps += 1

    return num_traps + (m - 1)

