from collections import defaultdict

def determine_winner(smaller, stack_size):
    if smaller > len(smaller) * 2 - 1 or stack_size < len(smaller):
        return False
    smaller.sort()
    stack = []
    for i in range(len(smaller)):
        while stack and smaller[i] < stack[-1]:
            stack.pop()
        if len(stack) == stack_size:
            return False
        stack.append(smaller[i])
    return True

def play_game(A):
    smaller = sorted(A)
    shorter = 1
    game_count = 0
    for x in A:
        if x != shorter:
            shorter = x
            game_count += 1
        if determine_winner(smaller, shorter):
            game_count -= 1
    return game_count

def main():
