def game_winner(stones, N):
    total_piles = len(stones)
    segment_piles = {}
    for i in range(total_piles):
        if stones[i] in segment_piles:
            segment_piles[stones[i]].append(i)
        else:
            segment_piles[stones[i]] = [i]

    results = []
    for i in range(1, total_piles + 1):
        if len(segment_piles[i]) > 0:
            results.append(len(segment_piles[i])/len(segment_piles) - 1)

