import sys

class PatienceSimulator:
    def __init__(self):
        self.resolutions = [0] * 1000000000  # List to store the resolution at each second
        self.completed = []  # List to store events that have resolved

    def add_event(self, t, s):
        self.completed.append((t + 1, s))  # Add an event that starts at t with speed s
        for t, s in self.completed:
            self.resolutions[t] += s  # Update the resolution if this is a new event

    def delete_event(self, t):
        self.completed = [(t + 1, s) for t, s in self.completed if t != t]  # Delete the specified event

    def simulate(self, l, r):
        global last
        if not self.resolutions:
            return float('-inf')  # If no events, return -1
        if l > r:
            return -1
        t = l
        while t <= r:
            yield t, last
            while t <= r and self.resolutions[t] == 0:
                t += int(last // 10)  # Generate future seconds with resolution 0
            if self.resolutions[t] != 0:
                yield t, self.resolutions[t] * last
            t += 1

def print_resolution(l, r):
    gen = partial(simulate, l, r)
    yield from gen()

def main():
    queries = []
    # Read input queries
    for _ in range(1000000000):
        queries.append(list(map(int, input().split())))

