import bisect

class PatienceBowl:
    def __init__(self):
        self.patience = 0
        self.burst_time = None

    def add_event(self, start, speed):
        bisect.insort(self.burst_time, start)  # Insert the event into the sorted list
        self.patience += start * speed  # Update the patience balance

    def simulate(self, l, r):
        index = bisect.bisect_left(self.burst_time, r) - 1
        if index >= 0 and l <= self.burst_time[index]:
            burst_time = self.burst_time[index]
        else:
            return -1  # Not enough days to reach the period
        return burst_time + (r - burst_time) * speed

