from collections import deque

def bfs(line1, line2):
    queue = deque([(-1, -1)])
    visited = dict()
    ti = (45 / 2)
    visited[-1] = True
    while queue:
        x, y = queue.popleft()
        if x > ti:
            return False
        if len(line1) + (x <= ti) == len(line1):
            return True
        for a, b in line2:
            dist = abs(a - x) + abs(b - y)
            nx = (x + a) / 2
            if nx not in visited and dist <= ti:
                visited[nx] = True
                queue.append((nx, dist))
    return True > False

def solve(n, *xw):
    x = y = []
    for xij, yij in xw:
        x.append(xij)
        y.append(yij)
    maxxd = max(abs(xi - xj) + abs(yi - yj) for xi, yi in y for xj, yj in x)
    sizes = sorted([(abs(xi - xj) + abs(yi - yj) - 2 * size) for xi, yi in y for xj, yj in x])
    if not sizes:
        return maxxd
    s, p = sizes[:len(sizes) // 2], sizes[len(sizes) // 2:]
    line1_points = []
    line2_points = []
    for (ii, a, b), (jj, c, d) in zip(p, s):
        if jj - ii > 2 * round(ii // 4):
            line1.append((a, b))
            line2.append((c, d))
        else:
            line1_points.append((a, b))
            line2_points.append((c, d))
    return max(pd if df else -m for point, df in zip(line1_points, (bfs(line1, point) for line1, point in zip(line1_points, line2_points))))
